          ..write('warnings: $warnings, ')
          ..write('imagePath: $imagePath, ')
          ..write('isSellable: $isSellable, ')
          ..write('isArchived: $isArchived, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt')
          ..write(')'))
        .toString();
  }
}

